 75	    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
 76	        if (email == null || email.trim().isEmpty()) {
 77	            throw new Xxd47Exception("사용자 이메일이 없습니다.");
 78	        }
 79	        if (productSizeId == null) {
 80	            throw new Xrf10Exception("상품 사이즈 ID가 없습니다.");
 81	        }
 82	        if (bidPrice <= 0) {
 83	            throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 84	        }
 85	    }
