   235	            return;
   236	        }
   239	        switch (currentStatus) {
   240	            case IN_STORAGE:
   242	                break;
   243	            case ASSOCIATED_WITH_ORDER:
   244	                if (newStatus == Xbj14Status.IN_STORAGE) {
   245	                    throw new Xfw62Exception(
   246	                            "주문과 연결된 상태(ASSOCIATED_WITH_ORDER)에서 보관 상태(IN_STORAGE)로 직접 전환할 수 없습니다.");
   247	                }
   248	                break;
   249	            case ON_AUCTION:
   250	                if (newStatus != Xbj14Status.IN_STORAGE && newStatus != Xbj14Status.SOLD) {
   251	                    throw new Xfw62Exception(
   252	                            "경매 중인 상태(ON_AUCTION)에서는 보관 상태(IN_STORAGE) 또는 판매됨(SOLD) 상태로만 전환할 수 있습니다.");
   253	                }
   254	                break;
   255	            case SOLD:
